{"file_text": ".apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    justify-content: space-between;
    margin-bottom: 2rem;
    padding: 0;
    gap: 0.25rem;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border: none;
    background: none;
    cursor: default;
    flex: 1;
    border-bottom: 3px solid transparent;
    transition: all 0.2s;
}

.step-indicator .step.current {
    border-bottom-color: #2563eb;
    color: #2563eb;
    font-weight: 600;
}

.step-indicator .step.completed {
    border-bottom-color: #16a34a;
    color: #16a34a;
    cursor: pointer;
}

.step-indicator .step.future {
    color: #9ca3af;
}

.step-number {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    font-size: 0.875rem;
    border: 2px solid currentColor;
}

.step.completed .step-number {
    background: #16a34a;
    color: white;
    border-color: #16a34a;
}

.step.current .step-number {
    background: #2563eb;
    color: white;
    border-color: #2563eb;
}

.checkmark {
    font-weight: bold;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
}

/* Step Content */
.step-content {
    background: #f9fafb;
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #111827;
}

.step-description {
    color: #6b7280;
    margin-bottom: 1rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    color: #374151;
    font-size: 0.875rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    box-sizing: border-box;
}

.form-group textarea {
    min-height: 6rem;
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-weight: normal !important;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Cover Letter */
.cover-letter-input {
    min-height: 12rem !important;
    font-family: inherit;
}

.char-count {
    text-align: right;
    font-size: 0.75rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e5e7eb;
}

.btn-next, .btn-submit {
    padding: 0.625rem 1.5rem;
    background: #2563eb;
    color: white;
    border: none;
    border-radius: 0.375rem;
    cursor: pointer;
    font-weight: 500;
    margin-left: auto;
}

.btn-next:hover, .btn-submit:hover {
    background: #1d4ed8;
}

.btn-next:disabled, .btn-submit:disabled {
    background: #93c5fd;
    cursor: not-allowed;
}

.btn-back {
    padding: 0.625rem 1.5rem;
    background: white;
    color: #374151;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    cursor: pointer;
    font-weight: 500;
}

.btn-back:hover {
    background: #f3f4f6;
}

.btn-add {
    padding: 0.5rem 1rem;
    background: white;
    color: #2563eb;
    border: 1px dashed #2563eb;
    border-radius: 0.375rem;
    cursor: pointer;
    width: 100%;
    margin-top: 1rem;
}

.btn-add:hover {
    background: #eff6ff;
}

.btn-remove {
    padding: 0.25rem 0.75rem;
    background: white;
    color: #dc2626;
    border: 1px solid #fca5a5;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.75rem;
}

.btn-remove:hover {
    background: #fef2f2;
}

.btn-edit {
    padding: 0.25rem 0.75rem;
    background: none;
    color: #2563eb;
    border: none;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
}

/* Work Entry & Reference */
.work-entry, .reference-entry {
    border: 1px solid #e5e7eb;
    border-radius: 0.375rem;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: white;
}

.work-entry-header, .reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4, .reference-header h4 {
    margin: 0;
    color: #374151;
}

/* Validation */
.validation-error {
    background: #fef2f2;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-top: 1rem;
    font-size: 0.875rem;
}

.field-error {
    color: #dc2626;
    font-size: 0.75rem;
    margin-top: 0.25rem;
    display: block;
}

/* Review Step */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #e5e7eb;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section-header h3 {
    margin: 0;
    color: #111827;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #6b7280;
}

.review-section dd {
    margin: 0;
}

.review-work-entry, .review-reference {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f3f4f6;
}

.review-work-entry:last-child, .review-reference:last-child {
    border-bottom: none;
}

.date-range {
    font-size: 0.875rem;
    color: #6b7280;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: white;
    padding: 1rem;
    border-radius: 0.375rem;
    border: 1px solid #e5e7eb;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 2rem;
}

.submission-confirmation h3 {
    color: #16a34a;
    font-size: 1.5rem;
}
