@page "/apply"
@rendermode InteractiveServer
@namespace sv_ec145c48c4e74868b79b00992b0bafc0.Components.Pages.Apply
@using sv_ec145c48c4e74868b79b00992b0bafc0.Models
@using static WorkEntryForm
@using static ReferenceForm

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalFullName"
                              Email="@personalEmail"
                              Phone="@personalPhone"
                              Address="@personalAddress"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep Personal="@GetPersonalResult()"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEditSection="GoToStep"
                        OnBack="GoBack"
                        OnSubmitted="HandleSubmitted" />
            break;
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();

    // Personal Info state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";

    // Work History state
    private List<WorkEntryModel> workEntries = new() { WorkEntryModel.Empty() };

    // References state
    private List<ReferenceModel> references = new() { ReferenceModel.Empty(), ReferenceModel.Empty() };

    // Cover Letter state
    private string coverLetter = "";

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalFullName = result.FullName;
        personalEmail = result.Email;
        personalPhone = result.Phone;
        personalAddress = result.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private void HandleSubmitted(int applicationId)
    {
        completedSteps.Add(4);
    }

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0)
        {
            currentStep--;
        }
    }

    private ReviewStep.PersonalInfoResult GetPersonalResult() =>
        new(personalFullName, personalEmail, personalPhone, personalAddress);
}

