        OnChanged.InvokeAsync(Entry with { Title = e.Value?.ToString() ?? "" });

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            OnChanged.InvokeAsync(Entry with { StartDate = date });
    }

