    {
        var val = e.Value?.ToString();
        var endDate = string.IsNullOrEmpty(val) ? (DateTime?)null : DateTime.Parse(val);
        OnChanged.InvokeAsync(Entry with { EndDate = endDate });
    }

    private void OnDescriptionChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Description = e.Value?.ToString() ?? "" });

