    [Parameter, EditorRequired] public EventCallback<ReferenceModel> OnChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }

    private void OnNameChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Name = e.Value?.ToString() ?? "" });

    private void OnRelationshipChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Relationship = e.Value?.ToString() ?? "" });

    private void OnEmailChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Email = e.Value?.ToString() ?? "" });

    private void OnPhoneChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Phone = e.Value?.ToString() ?? "" });

    public record ReferenceModel(string Name, string Relationship, string Email, string Phone)
    {
        public static ReferenceModel Empty() => new("", "", "", "");
    }
}

